    model_key = _model_id(captured["config"])
    datasets = []
    seen = []
    for item in CASES.values():
        key = item["dataset_id"]
        if key in seen:
            continue
        seen.append(key)
        profile = _profile(service, project, identity, key)
        datasets.append(
