def scaffold_document(brief: dict[str, Any]) -> dict[str, Any]:
    """根据报告简报建立可编辑文档骨架，不自动生成业务结论。"""

    template = brief.get("template", "analysis")
    templates = {
        "analysis": ["执行摘要", "数据与方法", "结果证据", "讨论", "结论", "来源"],
        "validation": [
            "执行摘要",
            "验证目标与判据",
            "数据与方法",
            "结果证据",
            "偏差与风险",
            "结论",
            "来源",
        ],
        "weekly": ["本周结论", "进展与关键指标", "结果证据", "问题与风险", "下周计划", "来源"],
        "blank": ["未命名章节"],
