@router.get("/api/visualizations")
def api_visualizations(
    request: Request,
    context_id: str | None = None,
    artifact_id: str | None = None,
    kind: str | None = None,
    renderer: str | None = None,
    dataset_id: str | None = None,
    include_payload: bool = False,
) -> dict:
    """按资产、数据集、类型或渲染器列出可视化资产。"""

    if context_id:
        from . import list_assets

        return {"items": list_assets(request.app.state.runtime.context(context_id)["scope"])}
    items = list_visualizations(
        artifact_id=artifact_id, kind=kind, renderer=renderer, dataset_id=dataset_id
    )
    result = []
    for item in items:
        payload = item.get("payload") or {}
        artifact = payload.get("artifact") or {}
        public = {
            "visualization_id": item["visualization_id"],
            "artifact_id": item["artifact_id"],
            "spec_id": item["spec_id"],
            "spec_version": item["spec_version"],
            "function_id": item["function_id"],
            "renderer": item["renderer"],
            "status": item["status"],
            "created_at": item["created_at"],
            "updated_at": item.get("updated_at") or item["created_at"],
            "name": artifact.get("name") or item["visualization_id"],
            "kind": artifact.get("kind"),
            "family": artifact.get("family"),
            "takeaway": artifact.get("takeaway"),
            "parameters": item["parameters"],
            "representations": item.get("representations", {}),
            "content_hash": item["content_hash"],
        }
        if include_payload:
            public["payload"] = payload
        result.append(public)
    return {
        "items": result,
        "updated_at": max((item["updated_at"] for item in result), default=None),
    }


