def parameter_contract(
    function: dict[str, Any],
    profile: dict[str, Any] | None = None,
    encoding: dict[str, Any] | None = None,
) -> dict[str, Any]:
    """根据方法、数据画像和字段映射生成JSON Schema与默认参数。"""

    profile = profile or {}
    encoding = encoding or {}
    kind = function["compatible_kinds"][0]
    function_id = function["id"]
    renderer = function["renderer"]
    fields = _field_choices(profile)
    numeric = [
        value for value in profile.get("numeric_columns", []) or [] if isinstance(value, str)
    ] or fields
    properties = _common_properties()

    if kind == "scalar":
        properties.update(
            {
                "unit": {"type": "string", "title": "单位", "maxLength": 24, "default": ""},
